/* Ver.158: desktop workspace expansion with an auto-collapsing left sidebar. */

.desktop-sidebar-pin-v158 {
  display: none;
}

@media (min-width: 861px) {
  body.desktop-sidebar-v158 .app-shell {
    grid-template-columns: 68px minmax(0, 1fr) !important;
    transition: grid-template-columns .18s ease;
  }

  body.desktop-sidebar-v158.desktop-sidebar-pinned .app-shell {
    grid-template-columns: 276px minmax(0, 1fr) !important;
  }

  body.desktop-sidebar-v158 .main {
    min-width: 0 !important;
  }

  body.desktop-sidebar-v158 .sidebar {
    width: 68px !important;
    min-width: 68px !important;
    max-width: none !important;
    padding: 12px 8px 18px !important;
